entries[19951] = { ["name"] = "Gri'lek's Charm of Might", ["text"] = "Binds when picked up\nUnique\nTrinket\nClasses: Warrior\nRequires Level 60\nUse: Instantly increases your rage by 30. (3 Min Cooldown)\n\nVindicator's Battlegear (0/5)\nGri'lek's Charm of Might\nRage of Mugamba\nZandalar Vindicator's Armguards\nZandalar Vindicator's Belt\nZandalar Vindicator's Breastplate\n(2) Set : Increases your chance to block attacks with a shield by 2%.\n(3) Set : Decreases the cooldown of Intimidating Shout by 15 sec.\n(5) Set : Decrease the rage cost of Whirlwind by 3." }
entries[19952] = { ["name"] = "Gri'lek's Charm of Valor", ["text"] = "Binds when picked up\nUnique\nTrinket\nClasses: Paladin\nRequires Level 60\nUse: Increases the critical hit chance of Holy spells by 10% for 15 sec. (3 Min Cooldown)\n\nFreethinker's Armor (0/5)\nGri'lek's Charm of Valor\nHero's Brand\nZandalar Freethinker's Armguards\nZandalar Freethinker's Belt\nZandalar Freethinker's Breastplate\n(2) Set : Restores 4 mana per 5 sec.\n(3) Set : Reduces the casting time of your Holy Light spell by 0.1 sec.\n(5) Set : Increases the duration of all Blessings by 10%." }
entries[19953] = { ["name"] = "Renataki's Charm of Beasts", ["text"] = "Binds when picked up\nUnique\nTrinket\nClasses: Hunter\nRequires Level 60\nUse: Instantly clears the cooldowns of Aimed Shot, Multishot, Volley, and Arcane Shot. (3 Min Cooldown)\n\nPredator's Armor (0/5)\nMaelstrom's Wrath\nRenataki's Charm of Beasts\nZandalar Predator's Bracers\nZandalar Predator's Belt\nZandalar Predator's Mantle\n(2) Set : +20 Attack Power.\n(3) Set : Decreases the cooldown of Concussive Shot by 1 sec.\n(5) Set : Increases the duration of Serpent Sting by 3 sec." }
entries[19954] = { ["name"] = "Renataki's Charm of Trickery", ["text"] = "Binds when picked up\nUnique\nTrinket\nClasses: Rogue\nRequires Level 60\nUse: Instantly increases your energy by 60. (3 Min Cooldown)\n\nMadcap's Outfit (0/5)\nZandalarian Shadow Mastery Talisman\nRenataki's Charm of Trickery\nZandalar Madcap's Bracers\nZandalar Madcap's Mantle\nZandalar Madcap's Tunic\n(2) Set : +20 Attack Power.\n(3) Set : Decreases the cooldown of Blind by 20 sec.\n(5) Set : Decrease the energy cost of Eviscerate and Rupture by 5." }
